169: async function fetchPointElevationMeters(lngLat: LngLat, signal: AbortSignal): Promise<number | null> {
170:   const [lng, lat] = lngLat;
171:   const url = `https://api.open-meteo.com/v1/elevation?latitude=${lat}&longitude=${lng}`;
172:   const response = await fetch(url, { signal });
173:   if (!response.ok) return null;
174:   const data = (await response.json()) as { elevation?: number[] };
175:   const v = data.elevation?.[0];
176:   return typeof v === "number" && Number.isFinite(v) ? v : null;
